let state; let people=[]; let interval=0; let sceneRoot=null; let routeObserver=null; let currentWorld='gi'; let rosters={gi:[],hsr:[],ww:[]}; let rosterLoaded={gi:false,hsr:false,ww:false}; let pixelFrame=0;
