function save(){state.lastAt=Date.now();state.storedByWorld??={gi:0,hsr:0,ww:0};state.storedByWorld[state.world]=state.stored;state.worldInventories??={};for(const wid of Object.keys(WORLDS))state.worldInventories[wid]??=zeroResources();state.worldInventories[state.world]={...zeroResources(),...state.resources};state.crewByWorld??={};state.crewByWorld[state.world]=JSON.parse(JSON.stringify(state.characters));try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{}}
function load(){try{const x=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(x&&x.version===VERSION){const base=defaults(),savedWorlds=x.worldInventories||{};const worlds=Object.fromEntries(Object.keys(WORLDS).map(wid=>[wid,{...base.resources,...(savedWorlds[wid]||{})}]));if(!savedWorlds[x.world]&&x.resources)worlds[x.world]={...base.resources,...x.resources};const out={...base,...x,wallets:{...base.wallets,...x.wallets},buildings:{...base.buildings,...x.buildings},characters:{...base.characters,...x.characters},crewByWorld:{...base.crewByWorld,...x.crewByWorld},worldInventories:worlds,items:{...base.items,...x.items},combat:{...base.combat,...x.combat}};out.crewByWorld[out.world]??={...starterCrews[out.world]};out.characters={...starterCrews[out.world],...out.crewByWorld[out.world]};out.resources={...base.resources,...worlds[out.world]};out.storedByWorld={gi:0,hsr:0,ww:0,...x.storedByWorld};out.stored=Number(x.storedByWorld?.[out.world]??x.stored??0);return out}}catch{}return defaults()}
function activePerson(){return people.find(p=>keyOf(p)===state.characters.active)||people.find(p=>keyOf(p)===state.characters.owned[0])||people[0]}
function keyOf(p){if(p?._expressKey)return p._expressKey;return String(p?._name||p?.name||p?.en||p?.key||p?.id||p?._id||'').toLowerCase().replace(/[^a-z0-9]+/g,'')}
function personByKey(key){return people.find(p=>keyOf(p)===key)||null}
function personName(p){return p?._name||p?.name||p?.en||'Voyageur'}
function personIcon(p){const identity=visualIdentity(p,keyOf(p),currentWorld);if(identity.portrait)return identity.portrait;if(currentWorld==='ww'&&/^[0-9]+$/.test(String(p?.id||p?._id||'')))return `/assets/express-roster/ww/${p.id||p._id}.webp`;if(currentWorld==='gi'&&['amber','kaeya','lisa','barbara'].includes(keyOf(p)))return `/assets/express-team/${keyOf(p)}.png`;return p?._quizImage||p?.icon||p?.images?.icon||p?.image||''}
function portrait(p,size=''){const url=personIcon(p);return url?`<img class="exw-portrait ${size}" src="${esc(url)}" alt="${esc(personName(p))}" loading="lazy"${p.portraitPosition?` style="object-position:${esc(p.portraitPosition)}"`:""}>`:`<span class="exw-portrait exw-fallback ${size}" aria-label="${esc(personName(p))}">${esc((personName(p)[0]||'✦').toUpperCase())}</span>`}
function placeOf(w,id){return (WORLDS[w]?.places||[]).find(p=>p[0]===id)||WORLDS[w].places[0]}
function placeArt(w,id){const p=placeOf(w,id);return p[3]?`/assets/relations/regions/${p[3]}`:w==='hsr'?'/assets/ui/game-starrail.png':'/assets/ui/game-wuthering.png'}
function log(msg){state.log.unshift({msg,at:Date.now()});state.log=state.log.slice(0,18)}
function addCurrency(n){state.wallets[moneyKey()]=Math.max(0,wallet()+n)}
function questProgress(){return Math.max(0,QUESTS.length-state.questDone.length)}
function checkQuests(){for(const q of QUESTS){if(!state.questDone.includes(q.id)&&q.test(state)){state.questDone.push(q.id);state.xp+=q.reward.xp;addCurrency(q.reward.mora);log(`Mission accomplie : ${q.title} · +${q.reward.xp} XP`);toast(`✦ ${q.title} · récompense reçue`)}}for(const badge of ACHIEVEMENTS)if(!state.achievements.includes(badge.id)&&badge.test(state)){state.achievements.push(badge.id);state.xp++;log(`Trophée obtenu : ${badge.name}.`)}state.level=1+Math.floor(state.xp/5);save()}
function toast(msg){const n=document.querySelector('.exw-toast');if(!n)return;n.textContent=msg;n.classList.add('is-visible');clearTimeout(n._t);n._t=setTimeout(()=>n.classList.remove('is-visible'),2400)}
function buffFactor(type){const p=activePerson(),kit=HERO_KITS[p?.name]||HERO_KITS[p?._name]||[];return kit.reduce((sum,item,i)=>sum+(item[2]===type&&state.buffs[`${keyOf(p)}:${i}`]?item[3]:0),0)}
function production(){const p=activePerson(),cx=clickEconomy(state,p,keyOf(p));const mult=cx.auto*(Date.now()<state.buffsUntil?1.5:1)*(state.fairy==='double'&&Date.now()<state.fairyUntil?2:1)*(1+buffFactor('production'))*(state.linked?1.25:1);return (state.buildings.collector*(.5+(state.research.irrigation||0)*.1)*mult+state.buildings.workshop*.16*mult)*industryBonuses(state).auto}
function settleOffline(){advanceIndustry(state);const now=Date.now(),elapsed=Math.min(8*3600,Math.max(0,(now-(Number(state.lastAt)||now))/1000));if(elapsed>3){const gain=production()*elapsed;state.stored+=gain;state.offlineSeconds=elapsed;log(`Pendant ton absence, le camp a produit ${fmt(gain,1)} ressources.`)}state.lastAt=now;save()}
function tick(){advanceIndustry(state);if(state.combo&&Date.now()-state.lastTap>1600)state.combo=0;const now=Date.now(),elapsed=Math.min(1.1,Math.max(0,(now-state.lastAt)/1000));if(elapsed>0){state.stored+=production()*elapsed;state.lastAt=now;if(state.trip&&now>=state.trip.end){const delivered=state.trip.cargo;state.cargoDelivered+=delivered;state.shipments++;state.wallets.credits+=Math.ceil(delivered*.4);state.trip=null;log(`Colis livrés : ${delivered} à ${state.place==='jinzhou'?'Jinzhou':'la destination'}.`);checkQuests();render()}}if(state.screen==='home'){creditCombat(tickAdventure(state,people,keyOf));updateClicker()}else updateHud();if(Math.floor(now/5000)!==Math.floor((now-1000)/5000))save()}
function updateHud(){for(const n of document.querySelectorAll('[data-hud-money]'))n.textContent=fmt(wallet(),1);for(const n of document.querySelectorAll('[data-hud-stored]'))n.textContent=fmt(state.stored,1);for(const n of document.querySelectorAll('[data-hud-rate]'))n.textContent=fmt(production(),1);for(const n of document.querySelectorAll('[data-hud-level]'))n.textContent=state.level;for(const n of document.querySelectorAll('[data-hud-combo]'))n.textContent=state.combo;for(const n of document.querySelectorAll('[data-collect]'))n.disabled=state.stored<1}
