function render(){industry(state);stopUltimateMedia();document.querySelectorAll('[data-exw-portal]').forEach(n=>n.remove());const el=document.querySelector('[data-genshin-idle]');if(!el)return;el.innerHTML=`<main class="express-worlds ${state.screen==='home'?'is-clicker':''}" ${presentationAttrs()} data-world-root><div class="exw-topline"><span><i>●</i> PROGRESSION AUTOMATIQUEMENT SAUVEGARDÉE</span><div>${button(state.reducedMotion?'Mouvement réduit':'Mouvement normal','reduced-motion')} ${button(state.pixel?'Vue illustrée':'Vue pixel art','pixel')} ${button('Partager mon carnet','share')} ${button('Sauvegarder','export')}</div></div>${renderExpressTools()}${worldsBar()}${state.screen==='home'?`<div class="cx-tools">${nav(true)}</div>`:hero()+walletBar()}<div class="exw-main-layout"><aside>${nav()}<section class="exw-sidebar-tip"><span>✧</span><small>CONSEIL DU VOYAGEUR</small><p>${state.buildings.collector?'Réclame tes ressources avant de partir.':'Cueille des fleurs pour financer ton premier collecteur.'}</p></section></aside><section class="exw-screen">${screenContent()}</section></div><footer class="exw-footer"><span>ASTRALIS · EXPRESS DES MONDES</span><span>Partie locale · enregistrée à l’instant</span><span>Les animations respectent la préférence de mouvement réduit.</span></footer><div class="exw-toast" role="status" aria-live="polite"></div>${state.tutorial.done?fairyModal():''}${state.tutorial.done?'':tutorialOverlay()}</main>`;el.querySelectorAll('.exw-modal-backdrop,.exw-tutorial-scrim').forEach(mountOverlay);if(state.screen==='home'){creditCombat(tickAdventure(state,people,keyOf));updateClicker()}else updateHud();attach();if(state.screen==='express'&&!state.pixel)buildThree();else destroyThree();if(state.screen==='express'&&state.pixel)drawPixelScene()}
