function mountOverlay(overlay){if(!overlay)return;overlay.dataset.exwPortal='true';document.body.append(overlay);overlay.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.exw==='tutorial-start'){state.tutorial.done=true;state.tutorial.step=1;save();render();toast('La première mission est dans ton journal.');return}if(b.dataset.fairy){state.fairy=b.dataset.fairy;state.fairySeen=true;if(state.fairy==='double')state.fairyUntil=Date.now()+20000;else state.fairyCharges=10;log(`La fée a choisi : ${b.dataset.fairy==='tap'?'récolte chanceuse':'souffle accéléré'}.`);save();checkQuests();render()}})}
function rosterIdentity(p){const id=String(p?.id??p?._id??'');return /^\d+$/.test(id)?id:'name:'+String(p?._name||p?.name||p?.en||id).toLowerCase().replace(/[^a-z0-9]/g,'')}
function prepareRoster(rows,wid){
 const byId=new Map(rows.map(p=>[rosterIdentity(p),p])),items=[...byId.values()],base=p=>String(p?._name||p?.name||p?.en||p?.id||'').toLowerCase().replace(/[^a-z0-9]/g,''),numericNames=new Set(items.filter(p=>/^\d+$/.test(rosterIdentity(p))).map(base));
 const filtered=items.filter(p=>/^\d+$/.test(rosterIdentity(p))||!numericNames.has(base(p))),counts={};for(const p of filtered)counts[base(p)]=(counts[base(p)]||0)+1;
 const reserved=wid==='hsr'?{'1001':'march7th','1002':'danheng','1003':'himeko','1009':'asta'}:wid==='ww'?{'1402':'yangyang','1202':'chixia','1103':'baizhi','1501':'rover'}:{};
 return filtered.map(p=>{const id=rosterIdentity(p),name=base(p),same=filtered.filter(q=>base(q)===name),first=same.find(q=>reserved[rosterIdentity(q)])||same[0];return {...p,_expressKey:reserved[id]||(counts[name]>1&&p!==first?name+id:name)}})
}
function ensurePeople(list){if(currentWorld==='gi'&&list?.length)rosters.gi=list;const local=(localRoster.catalogs[currentWorld+':character']||[]).map(p=>({...p,_name:p.name,id:p.id,icon:p.images?.icon||p.images?.image||'',_quizImage:p.images?.icon||p.images?.image||''}));const kits=currentWorld==='gi'?Object.values(labRoster.characters).filter(p=>p.id).map(p=>({id:p.id,name:p.name,_name:p.name,rarity:5,_quizImage:'/assets/character-portraits/gi-'+p.id+'.webp'})):[];rosters[currentWorld]=[...kits,...local,...(rosters[currentWorld]||[])];people=prepareRoster([...(rosters[currentWorld]||[]),...(LORE_COMPANIONS[currentWorld]||[])],currentWorld);people=[...new Map(people.map(p=>[keyOf(p),p])).values()];const names=currentWorld==='hsr'?['March 7th','Dan Heng','Himeko','Asta']:currentWorld==='ww'?['Yangyang','Chixia','Baizhi','Rover']:['Amber','Kaeya','Lisa','Barbara'];const elements={Amber:'Pyro',Kaeya:'Cryo',Lisa:'Électro',Barbara:'Hydro','March 7th':'Ice','Dan Heng':'Wind',Himeko:'Fire',Asta:'Fire',Yangyang:'Aero',Chixia:'Fusion',Baizhi:'Spectro',Rover:'Spectro'};for(const name of names)if(!people.some(p=>keyOf(p)===keyOf({name})))people.push({id:name.toLowerCase(),name,rarity:4,elementText:elements[name]||'Physique'});if(!state.characters.owned.length)state.characters.owned=[...starterCrews[currentWorld].owned];const map=new Set(people.map(keyOf));if(!state.characters.owned.length)state.characters.owned=[...starterCrews[currentWorld].owned];if(!state.characters.owned.includes(state.characters.active))state.characters.active=state.characters.owned[0];rosters[currentWorld]=people;teamState(state)}
async function loadWorldRoster(wid){
 if(wid==='gi'){ensurePeople(rosters.gi);return}if(!rosterLoaded[wid]){ensurePeople();rosterLoaded[wid]=true;save();render();return;}
 if(rosterLoaded[wid]){if(state.world===wid)ensurePeople();return}
 if(!rosterLoaded[wid]){
  try{
   if(wid==='hsr'){
    const data=await fetch('./assets/data/hsr-nanoka-character.json').then(r=>r.json());
    rosters.hsr=Object.entries(data).map(([id,p])=>({id,name:p.en||p.ko||`Trailblazer ${id}`,elementText:p.damageType||'Imaginary',rarity:String(p.rank).includes('5')?5:4,icon:`https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/icon/character/${id}.png`,description:p.desc||''}));
   }else{
    const data=await fetch('./assets/data/ww-characters.json').then(r=>r.json());
    rosters.ww=data.map(p=>({id:p.id,name:p.name,elementText:p.element,rarity:p.rarity,icon:`/assets/express-roster/ww/${p.id}.webp`}));
   }
  }catch{if(!rosters[wid])rosters[wid]=[]}
  if(state.world===wid){ensurePeople();render()}
 }
 try{
  const data=await loadCatalog(wid,'character');
  if(data?.length){rosters[wid]=[...rosters[wid],...data.map(p=>({...p,_name:p._name||p.name||p.enName,_quizImage:imageSet(wid,p,'character')[0]||''}))];rosters[wid]=prepareRoster(rosters[wid],wid);}
 }catch{}
 rosterLoaded[wid]=true;if(state.world===wid){ensurePeople();save();render()}
}
function clickHarvest(resource='flower'){
 const c=initClicker(state),p=activePerson(),key=keyOf(p);state.taps++;state.combo=Date.now()-state.lastTap<1600?Math.min(25,state.combo+1):1;state.lastTap=Date.now();
 const e=clickEconomy(state,p,key),critical=resource==='flower'&&Math.random()<e.critChance,rate=e.click*(critical?e.critPower:1)+(state.fairyCharges>0?1:0),gain=resource==='flower'?rate:1;if(state.fairyCharges>0)state.fairyCharges--;
 state.resources[resource]=(Number(state.resources[resource])||0)+gain;if(resource==='flower'){addCurrency(gain);c.totalEarned+=gain;c.lastGain=gain;c.lastCritical=critical;c.regionClicks[`${state.world}:${state.place}`]=(c.regionClicks[`${state.world}:${state.place}`]||0)+1;creditCombat(combatHit(state,p,key,people,keyOf))}
 if(state.combo===5||state.taps%25===0)state.xp++;checkQuests();if(state.screen==='home'&&document.querySelector('[data-clicker]')){updateClicker();const stage=document.querySelector('[data-cx-stage]');stage?.classList.remove('just-clicked');if(stage){void stage.offsetWidth;stage.classList.add('just-clicked');playCharacterClick(stage,p,key,state.world,{reduced:state.reducedMotion,normal:true,amplified:activeEffects(state).length>0});}const text=document.querySelector('[data-cx-feedback]');if(text)text.textContent=`+${fmt(gain,2)} ${RESOURCE[state.world].name}${critical?' · RÉCOLTE DORÉE':''}`;const mote=document.createElement('i');mote.className='cx-float';mote.textContent=`+${fmt(gain,1)}`;mote.style.left=`${35+Math.random()*30}%`;stage?.append(mote);setTimeout(()=>mote.remove(),900)}else render()
}
