function showMoment(key,kind='resonance',strong=false){const p=personByKey(key);if(p)companionMoment(document.querySelector('[data-cx-stage]'),state,p,key,{kind,strong,image:personIcon(p)});}
function creditCombat(out){if(!out)return;playKitEvents(document.querySelector('[data-cx-stage]'),state,out.vfx,people,keyOf);if(out.resonance)showMoment(out.resonance.key);if(out.levels?.length){refreshBuild();const levels=out.levels.filter(x=>[5,10,20,35,50,75,100].includes(x.level));if(levels.length)toast(`Nouveau passif appris · niveau ${levels[0].level}`);}if(out.money){out.money*=industryBonuses(state).loot;addCurrency(out.money);state.resources.flower+=out.money;initClicker(state).totalEarned+=out.money;}if(out.items?.length){enqueueLoot(state,out.items);refreshLoot();refreshBuild();}const count=document.querySelector('[data-rpg-tab="build"] span');if(count)count.textContent=gearState(state).inventory.length;}
function updateClicker(){updateIndustryView(state);updateHud();const active=activePerson();restoreCharacterIdentity(document.querySelector('[data-cx-stage]'),state,active,keyOf(active),personIcon(active));if(!state.reducedMotion)warmUltimateClips(people.filter(p=>(state.clicker?.teams?.[state.world]||[]).includes(keyOf(p))),state.world);else releaseUltimatePreloads();restoreAftermath(document.querySelector('[data-cx-stage]'),state);restoreKitEntities(document.querySelector('[data-cx-stage]'),state,people,keyOf);updateAdventureView(state,people,combatHelpers());for(const b of document.querySelectorAll('[data-cx-buy]'))b.disabled=upgradeLevel(state,b.dataset.cxBuy)>=100||wallet()<upgradePrice(state,b.dataset.cxBuy);}
function launchTeamBurst(key){
 const p=personByKey(key);if(!p)return;const out=castPower(state,p,key,'burst',people,keyOf);if(!out.ok){toast(out.reason);return;}creditCombat(out);save();updateClicker();
 const stage=document.querySelector('[data-cx-stage]');showMoment(key,'burst',true);playUltimateMedia(stage,p,key,state.world,{muted:initClicker(state).mediaMuted,reduced:state.reducedMotion,buffLabel:out.kit.description,onComplete:()=>{if(!stage?.isConnected)return;startAftermath(state,p,key);restoreAftermath(stage,state);save()}});
 const feedback=document.querySelector('[data-cx-feedback]');if(feedback)feedback.textContent=`${personName(p)} · ${fmt(out.damage)} DGT${out.combo?' · '+out.combo:''}`;
}
function launchChargedAttack(){const p=activePerson(),key=keyOf(p),out=chargedAttack(state,p,key,people,keyOf);if(!out.ok){toast(out.reason);return;}creditCombat(out);save();updateClicker();showMoment(key,'charged',true);}
