 if(b.dataset.rpgAscend){const p=personByKey(b.dataset.rpgAscend),g=gearState(state),cost=p&&ascendHero(state,p,b.dataset.rpgAscend,wallet(),g.shards);if(cost){addCurrency(-cost.money);g.shards-=cost.shards;save();refreshBuild();updateClicker();showMoment(b.dataset.rpgAscend,'level',true)}return true}
 if(b.dataset.rpgLootEquip){equipGear(state,b.dataset.target||id,b.dataset.rpgLootEquip);dismissLoot(state,b.dataset.rpgLootEquip);save();refreshLoot();refreshBuild();updateClicker();return true}
 if(b.dataset.rpgLootLater){dismissLoot(state,b.dataset.rpgLootLater);save();refreshLoot();return true}
 if(b.dataset.rpgTab){c.rpgTab=b.dataset.rpgTab;save();render();return true}
 if(b.dataset.rpgBuildTarget){c.buildTargets??={};c.buildTargets[state.world]=b.dataset.rpgBuildTarget;save();refreshBuild();return true}
 if(b.dataset.rpgEquip){equipGear(state,b.dataset.target||c.buildTarget||id,b.dataset.rpgEquip);save();refreshBuild();updateClicker();return true}
 if(b.dataset.rpgUnequip){unequipGear(state,b.dataset.target||c.buildTarget||id,b.dataset.rpgUnequip);save();refreshBuild();updateClicker();return true}
 if(b.dataset.rpgUpgrade){upgradeGear(state,b.dataset.rpgUpgrade);save();refreshBuild();updateClicker();return true}
 if(b.dataset.rpgSalvage){salvageGear(state,b.dataset.rpgSalvage);save();refreshBuild();return true}
 if(b.hasAttribute('data-rpg-gear-page')){c.gearPage=Math.max(0,Number(b.dataset.rpgGearPage)||0);save();refreshBuild();return true}
 if(b.hasAttribute('data-rpg-sound')){c.mediaMuted=!c.mediaMuted;stopUltimateMedia();b.textContent=c.mediaMuted?'Son coupé':'Son actif';b.setAttribute('aria-pressed',c.mediaMuted);save();return true}
 if(b.hasAttribute('data-cx-team-edit')){c.editTeam=!c.editTeam;save();render();return true}
 if(b.dataset.cxTeamActive){if(teamKeys(state).includes(b.dataset.cxTeamActive)){switchCombatCharacter(state,b.dataset.cxTeamActive,people,keyOf);save();render()}return true}
