 if(b.dataset.cxView){const root=document.querySelector('[data-clicker]');if(b.dataset.cxView==='focus'){c.sceneFocus=!c.sceneFocus;root?.classList.toggle('scene-focus',c.sceneFocus);b.textContent=c.sceneFocus?'Vue complète':'Agrandir la scène';b.setAttribute('aria-pressed',String(c.sceneFocus))}else if(b.dataset.cxView==='calm'){c.calmScene=!c.calmScene;root?.classList.toggle('calm-scene',c.calmScene);b.textContent=c.calmScene?'Effets réduits':'Ambiance animée';b.setAttribute('aria-pressed',String(c.calmScene))}save();return true}
 if(b.dataset.cxBuy){const type=b.dataset.cxBuy;if(!['click','auto','combo','fortune'].includes(type))return true;const cost=upgradePrice(state,type);if(wallet()>=cost&&upgradeLevel(state,type)<100){addCurrency(-cost);c.upgrades[`${state.world}:${state.place}:${type}`]=upgradeLevel(state,type)+1;log(`${REGIONS[state.place]?.[0]} : amélioration ${type}, palier ${upgradeLevel(state,type)}.`);save();render()}return true}
 if(b.hasAttribute('data-cx-page')){c.page=Math.max(0,Number(b.dataset.cxPage)||0);save();render();return true}
 if(b.dataset.cxPower==='charged'){launchChargedAttack();return true}
 if(b.dataset.cxPower==='skill'){launchTeamSkill(id);return true}
