export function renderTeyvatTycoon(_game,characters=[]){state=load();currentWorld=state.world;ensurePeople(characters);if(currentWorld!=='gi')loadWorldRoster(currentWorld);if(location.hash.startsWith('#express=')){const params=new URLSearchParams(location.hash.slice(1).replaceAll('&','&'));state.seed=params.get('express')||state.seed;state.level=Math.max(state.level,Number(params.get('rank'))||1)}return `<div data-genshin-idle class="exw-mount"></div>`}
export function mountTeyvatTycoon(root,_game,characters=[],notify=()=>{}){if(!root)return;routeObserver?.disconnect();routeObserver=new MutationObserver(()=>{if(root.isConnected)return;stopUltimateMedia();releaseUltimatePreloads();if(state.clicker?.readDialogue)globalThis.speechSynthesis?.cancel();document.querySelectorAll('[data-exw-portal]').forEach(n=>n.remove());routeObserver?.disconnect();routeObserver=null});routeObserver.observe(document.body,{childList:true,subtree:true});state=load();currentWorld=state.world;ensurePeople(characters);settleOffline();if(currentWorld!=='gi')loadWorldRoster(currentWorld);preloadUltimateMedia();root.dataset.expressWorldsMounted='true';render();if(interval)clearInterval(interval);interval=setInterval(()=>{if(!root.isConnected){clearInterval(interval);interval=0;destroyThree();return}tick()},1000);window.addEventListener('pagehide',save,{once:true});document.documentElement.classList.toggle('exw-reduced-motion',state.reducedMotion);root.addEventListener('click',e=>{const b=e.target.closest('[data-exw="collect"]');if(b)notify('Récolte récupérée')})}
export function tycoonCabinTabs(mode='idle'){return `<nav class="idle-mode-tabs tycoon-cabin-tabs" aria-label="Cabine de Teyvat"><button type="button" data-cabin-mode="idle" class="${mode==='idle'?'is-active':''}"><span>✦</span> Express des Mondes</button><button type="button" data-cabin-mode="classic" class="${mode==='classic'?'is-active':''}"><span>✧</span> Genshin Idle</button><button type="button" data-cabin-mode="quiz" class="${mode==='quiz'?'is-active':''}"><span>⌕</span> Défi connaisseurs</button></nav>`}

export function expressCatalogueSummary(){return {world:state?.world,count:people.length,ids:people.map(p=>String(p.id||p._id||'')),owned:state?.characters?.owned?.length||0};}
